using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class Colette
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "La solide carrure d'Alexandre Georges plaît aux auditrices, non moins que sa \"Légende bretonne\", chantée très finement par Mlle Suzanne Dumesnil, bien disante, et qui n'a pas cru devoir, Dieu merci, pour plus de couleur locale, s'empâter la diction avec de la galette de sarrazin (sic).", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Salle Humbert de Romans, la vicomtesse de Trédern a chanté \"Ève\" de son mieux. Ce mieux est l'ennemi du bien.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Ça, une scène d'amour ? Ben, si j'avais l'extase aussi tumultueuse, je voudrais voir ce que diraient mes voisins d'en dessous. Il est vrai que le programme appelle ce chahut « scène » et non pas duo.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Quelle foule au Nouveau-Théâtre ! On y joue pourtant de l'excellente musique ! Si le public devient connaisseur, maintenant, c'est la fin du monde !", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Mlle Dangès vocalise un si déplorable air des Huguenots qu'elle ferme les yeux tout le temps, pour ne pas voir ce qu'elle chante.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "D'ailleurs, si on me repince à un concours d'instruments à vent ! Passe pour les bois, où je goûte le nasillement frais du hautbois et la gravité veloutée de la flûte.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Le Jardin-du-Haut commandait un Jardin-du-Bas, potager resserré et chaud, consacré à l’aubergine et au piment, où l’odeur du feuillage de la tomate se mêlait, en juillet, au parfum de l’abricot mûri sur espaliers.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Grande maison grave, revêche avec sa porte à clochette d’orphelinat, son entrée cochère à gros verrou de geôle ancienne, maison qui ne souriait que d’un côté.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Ma mère renversait la tête vers les nuées, comme si elle eût attendu qu’un vol d’enfants ailés s’abattît.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "J’avais, petite, le loisir de suivre, en courant presque, le grand pas des garçons, lancés dans les bois à la poursuite du Grand Sylvain, du Flambé, du Mars farouche, ou chassant la couleuvre, ou bottelant la haute digitale de juillet au fond des bois clairsemés, rougis de flaques de bruyères…", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Notre seul péché, notre méfait unique était le silence, et une sorte d’évanouissement miraculeux.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Il y a des jours où la boucherie de Léonore, ses couteaux, sa hachette, ses poumons de bœuf gonflés que le courant d’air irise et balance, roses comme la pulpe du bégonia, me plaisent à l’égal d’une confiserie.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "La robe de toile que je presse de ma joue sent le gros savon, la cire dont on lustre les fers à repasser, et la violette.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Le chocolat, dans ce temps-là, ça se faisait avec du cacao, du sucre et de la vanille. En haut de la maison, les briques de chocolat séchaient, posées toutes molles sur la terrasse.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Il n’est qu’un jeune chat, fruit des amours — et de la mésalliance — de Moune, chatte persane bleue, avec n’importe quel rayé anonyme.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Il fait beaucoup de bruit en tétant, parce que ses dents poussent… C’est un petit chat, innocent au milieu d’un drame.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Le bain quotidien, joie silencieuse et complète, rendait à leur âge difficile la paix et l'enfance, toutes deux en péril.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Elle le suivit sans mot dire, dans le sentier de la douane en corniche à flanc de falaise. Ils foulaient l'origan poivré et les derniers parfums du mélilot.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Des champignons moites sortaient de terre, et les araignées des jardins, à cause des nuits plus fraîches, rentraient le soir dans la resserre aux jouets et s'y rangeaient sagement au plafond.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Mme Dalleray ne semblait pas l'attendre et lisait. Mais l'ombre étudiée du salon, la table presque invisible d'où montaient les odeurs de la pêche tardive, du melon rouge de Chypre coupé en croissants d'astre et du café noir versé sur la glace pilée le renseignèrent.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "J'aime le courage féminin, son ingéniosité à organiser une vie blessée.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Une femme qui lutte contre son mal est un spectacle qu'on peut nommer édifiant.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Une absence totale d'humour rend la vie impossible.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Une conjecture nous semble unique parce que nous ne sommes pas assez subtils pour discerner qu'elle fait pendant, vêtue de neuf, à un vieux hasard identique…", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "« Ce qu'on trouve ne vaut pas toujours ce qu'on quitte. »", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Je n'ai guère approché, pendant ma vie, de ces hommes que les autres hommes appellent grands. Ils ne m'ont pas recherchée.", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Mais qu'aurais-je fait d'une vie qui n'eût été que roses ?", Author = "Colette" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Colette", Text = "Elles sont nombreuses, les filles à peine nubiles qui rêvent d'être le spectacle, le jouet, le chef-d'oeuvre libertin d'un homme mûr.", Author = "Colette" },
        };
    }
}